/**
 * @brief Render the splash image to the framebuffer
 * @param offset_x The x offset to start rendering the image
 * @param offset_y The y offset to start rendering the image
 */
void splash_render(int offset_x,int offset_y) {

  unsigned int x, y;
  unsigned int pixel_value;

  for (y = 0; y < (gimp_image.height); y++) {
      for (x = 0; x < (gimp_image.width); x++) {
          unsigned int index = (y * gimp_image.width + x) * gimp_image.bytes_per_pixel;

          unsigned char r = gimp_image.pixel_data[index + 0];
          unsigned char g = gimp_image.pixel_data[index + 1];
          unsigned char b = gimp_image.pixel_data[index + 2];

          pixel_value = (0xFF << 24) | (r << 16) | (g << 8) | b;

          vbe_fast_putpixel(x+offset_x,y+offset_y,pixel_value);
      }
  }
  vbe_flip();
}

/**
 * @brief Create a color render object
 * 
 * This function generates a gradient of colors across the screen. (makes it gay)
 * 
 */
void create_color_render(int height) {
  unsigned int r = 255, g = 0, b = 0;
  unsigned int color;
  int step_size = 1; // Control how many colors (larger step = fewer colors)

  for (int i = 0; i < NUM_STEPS; i++) {
    // integer hue from 0..1535 (≈ 6×256)
    // Multiply first to avoid truncating to zero too early
    int hue = (i * 1536) / NUM_STEPS; 
    int region = hue >> 8;       // hue / 256
    int offset = hue & 0xFF;     // hue % 256

    int r = 0, g = 0, b = 0;

    switch (region) {
        case 0: 
            // Red → Yellow:    R=255, G=0→255, B=0
            r = 255;       
            g = offset;    // from 0 up to 255
            b = 0;        
            break;
        case 1:
            // Yellow → Green:  R=255→0, G=255, B=0
            r = 255 - offset; 
            g = 255;         
            b = 0;            
            break;
        case 2:
            // Green → Cyan:    R=0, G=255, B=0→255
            r = 0;        
            g = 255;      
            b = offset;   // from 0 up to 255
            break;
        case 3:
            // Cyan → Blue:     R=0, G=255→0, B=255
            r = 0;         
            g = 255 - offset; 
            b = 255;       
            break;
        case 4:
            // Blue → Magenta:  R=0→255, G=0, B=255
            r = offset; // from 0 up to 255
            g = 0;       
            b = 255;     
            break;
        case 5:
            // Magenta → Red:   R=255, G=0, B=255→0
            r = 255;       
            g = 0;         
            b = 255 - offset; 
            break;
    }

    // Pack into 0xFFRRGGBB
    uint32_t packed = 0xFF000000 
                    | ((uint32_t)r << 16) 
                    | ((uint32_t)g << 8) 
                    | (uint32_t)b;
    vbe_fillrect(1*i, height, 1, 3, packed);
  }
}